  'Deze afbeelding naar het AI-model sturen?':
      'Lähetetäänkö tämä kuva tekoälymallille?',
  'De afbeelding gaat ongewijzigd naar':
      'Kuva lähetetään muuttumattomana kohteeseen',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck ei peitä kuvasta mitään: kasvot, kuvakaappauksen teksti ja näkyvät tiedot lähtevät mukana.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Kuvatarkistus löysi tästä yhdet tai useammat tunnistettavat kasvot.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Viennin viereen tallennetaan kaksi tiedostoa, joiden avulla vastaanottaja voi tarkistaa peitetyt kohdat.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'luettelee, mitä on jätetty pois, ilman itse arvoja. Tämän tiedoston saa lähettää raportin mukana.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'sisältää avaimet, joilla jokainen peitetty arvo voidaan laskea takaisin. Älä lähetä tätä tiedostoa mukana: silloin peittäminen kumoutuu. Säilytä se lähteen luona.',
  'slides': 'diaa',
  'Achtergehouden': 'Pidätetty',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Pidätetty: luokiteltu tiukemmin kuin esitys',
  '1 slide achtergehouden door haar TLP': '1 dia pidätetty sen TLP:n vuoksi',
  'slides achtergehouden door hun TLP': 'diaa pidätetty niiden TLP:n vuoksi',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Nämä diat jäävät pois esitettäessä, vietäessä ja paketista. Nosta esityksen TLP-tasoa kohdassa Esityksen tiedot, jotta ne tulevat mukaan.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Kaikki diat on pidätetty niiden TLP-luokituksen vuoksi, joten näytettävää ei ole.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Kaikki diat on pidätetty niiden TLP-luokituksen vuoksi, joten vietävää ei ole.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Kaikki diat on ohitettu tai pidätetty niiden TLP-luokituksen vuoksi, joten näytettävää ei ole.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Kaikki diat on ohitettu tai pidätetty niiden TLP-luokituksen vuoksi, joten vietävää ei ole.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Kaavion lukuja ei tallennettu — ne ovat enää vain tässä ikkunassa:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Selaimessa ei ole kaatumispalautusta: jos suljet tämän välilehden, tallentamaton työ katoaa. Tallenna esityksesi itse.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Paikallinen CVE-tietokanta (käynnistät latauksen itse): OciDeck hakee joukkotiedot osoitteen api.github.com kautta ja sen julkaisutiedoston, johon osoite viittaa.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE-haku (oletuksena pois päältä): kun se on päällä, hakusanasi menee asetettuun CVE-peilipalvelimeen ja, jos se ei löydä mitään, ENISAn eurooppalaiseen tietokantaan ja MITREen.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Upotettu YouTube- tai Vimeo-video lataa soittimen kyseiseltä palvelulta.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Selaimessa: jos selain kieltäytyy noutamasta osoitetta suoraan, OciDeck yrittää uudelleen sen palvelimen kautta, jolta sovellus tuli; osoite päätyy silloin tuolle palvelimelle.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Peruutusta ei tallennettu. Seuraavalla käynnistyskerralla suostumuksesi on jälleen voimassa.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Osion väliotsikko, joka ilmoittaa esityksen uudesta osasta. Pidä se lyhyenä. Lisää taustakuva kuvakirjastosta.',
  'Bronnen doorzoeken…': 'Haetaan lähteistä…',
  'Niet doorzocht': 'Ei haettu',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Tämä tarkistus ei toimi verkkoversiossa: kasvojen tunnistus vaatii järjestelmäkirjaston, jota selaimessa ei ole. Tarkista kuvien kasvot työpöytäversiolla.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Poletti tarvitsee luku- ja kirjoitusoikeuden repositorioon. Giteassa ja Forgejossa ei ole palvelinhakua; OciDeck hakee paikallisesti.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Poletti tarvitsee repo-alueen (tai tarkasti: Contents luku ja kirjoitus).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Poletti tarvitsee read_repository, write_repository ja read_api. Palvelinhaku edellyttää Advanced- tai Exact Search -toimintoa.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Nopea palvelinhaku — indeksoinnin viiveen vuoksi juuri muutettu pakka voi puuttua.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Mediaa ei säilytetä pelkässä .md-tiedostossa',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Tässä välilehdessä valitsemasi kuvat, video ja ääni ovat vain muistissa. Pelkkä .md-tiedosto ei säilytä niitä — ne katoavat, kun avaat sen uudelleen. Vie .ocideck-pakettina, jotta saat median mukaasi.',
  'Media verwijderd om privacyredenen': 'Media poistettu yksityisyyden vuoksi',
  'Afbeeldingen door AI laten taggen?':
      'Annetaanko tekoälyn merkitä nämä kuvat?',
  'afbeeldingen gaan naar': 'kuvaa lähetetään kohteeseen',
  'een model op dit apparaat': 'malli tässä laitteessa',
  'Doorgaan': 'Jatka',
  'Ontdekkingen': 'Löydöt',
  'Wat is gevonden': 'Mitä löytyi',
  'Soort': 'Laji',
  'Dagen onopgemerkt': 'Päivää huomaamatta',
  'Ontdekking toevoegen': 'Lisää löytö',
  'Ontdekking verwijderen': 'Poista löytö',
  'Kop van de slide': 'Dian otsikko',
  'dagen onopgemerkt': 'päivää huomaamatta',
  'Nog geen blootstelling ingevuld — de slide toont dan geen kop, alleen de lijst.':
      'Altistusaikaa ei ole vielä täytetty — dia ei silloin näytä otsikkoa, vain listan.',
  'Zes ontdekkingen is het maximum; wie er meer noemt maakt een bijlage in plaats van een slide.':
      'Kuusi löytöä on enimmäismäärä; useamman luetteleminen tekee liitteen eikä diaa.',
  'Laat de dagen leeg als de eerste blootstelling onbekend is; de slide zegt dan "onbekend" in plaats van nul. Een lege eigenaar leest als "geen eigenaar" en valt rood op.':
      'Jätä päivät tyhjiksi, jos ensimmäinen altistus on tuntematon; dia sanoo silloin "tuntematon" nollan sijaan. Tyhjä vastuuhenkilö luetaan muodossa "ei vastuuhenkilöä" ja erottuu punaisena.',
  'Wat de scan vond dat niemand wist te hebben. Per ontdekking hoe lang die onopgemerkt bereikbaar was en wie hem nu bezit; de langste blootstelling is de kop.':
      'Mitä skannaus löysi, mitä kukaan ei tiennyt omistavansa. Löydöittäin, kuinka kauan se oli tavoitettavissa huomaamatta ja kuka siitä nyt vastaa; pisin altistus on otsikko.',
  'dag': 'päivä',
