  'Scorecard': 'Tunnuslukukortti',
  'Cijfer toevoegen': 'Lisää tunnusluku',
  'Cijfer verwijderen': 'Poista tunnusluku',
  'Richting': 'Suunta',
  'ongewijzigd': 'ennallaan',
