  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'sairausvakuutusnumero (RAMQ) — terveystieto',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'sairausvakuutusnumero (OHIP) — terveystieto',
  'bedrijfsnummer (BN)': 'yritysnumero (BN)',
  'zorgverlenersnummer (NPI)': 'terveydenhuollon tuottajanumero (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'Medicare-numero (MBI) — terveystieto',
  'wacht op verbinding': 'odottaa yhteyttä',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Tallennettu tälle tietokoneelle, ei vielä repositorioon. Lähtee heti kun yhteys palaa — tai nyt, valinnalla "Tyhjennä jono".',
  'Branch (optioneel)': 'Haara (valinnainen)',
  'let op: de standaardbranch is': 'huomio: oletushaara on',
  'jij werkt op': 'sinä työskentelet haarassa',
  'werkgeversnummer (EIN)': 'työnantajanumero (EIN)',
  'laatste vier cijfers van een SSN': 'SSN-numeron neljä viimeistä numeroa',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'syntymäaika, postinumero ja sukupuoli yhdessä — nämä kolme osoittavat yleensä yhden henkilön, myös ilman nimeä',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Tämän palvelimen varmennetta ei luoteta. Itse ylläpidetyllä palvelimen voit tarkastella sitä ja luottaa siihen kohdassa Asetukset → Tallennus.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Tämän forge varmennetta ei luoteta. Itse ylläpidetyllä forge voit tarkastella sitä ja luottaa siihen kohdassa Asetukset → Tallennus.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Tämän päätepisteen varmennetta ei luoteta. Itse ylläpidetyllä päätepisteen voit tarkastella sitä ja luottaa siihen kohdassa Asetukset → Tallennus.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'forge varmennetta ei luoteta — itse allekirjoitettu, vanhentunut tai myönnetty toiselle nimelle.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'päätepisteen varmennetta ei luoteta — itse allekirjoitettu, vanhentunut tai myönnetty toiselle nimelle.',
  'creditcardnummer': 'luottokortin numero',
  'beveiligingscode van een creditcard': 'kortin turvakoodi (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'tietoja puhujan muistiinpanoissa — näkymättömiä dialla, mutta mukana viennissä',
  'Certificaat vertrouwen?': 'Luotetaanko tähän varmenteeseen?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Tämän palvelimen varmennetta ei ole allekirjoittanut tunnustettu myöntäjä. Se on tavallista itse ylläpidetyllä palvelimella, mutta myös salakuunneltu yhteys näyttää tältä.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Vertaa alla olevaa sormenjälkeä siihen, minkä palvelimesi itse näyttää. Jos ne täsmäävät, puhut oikean koneen kanssa.',
  'Uitgegeven aan': 'Myönnetty',
  'Uitgegeven door': 'Myöntäjä',
  'Geldig tot': 'Voimassa',
  'Vingerafdruk (SHA-256)': 'Sormenjälki (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Vain tähän yhteen varmenteeseen luotetaan. Jos palvelin vaihtaa sen myöhemmin, OciDeck kysyy uudelleen.',
  'Vertrouwen': 'Luota',
  'Certificaat bekijken': 'Näytä varmenne',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Paikat, joissa säilytät ja haet esityksiäsi — kansiot tällä tietokoneella, WebDAV-palvelimet, S3-ämpärit ja git-arkistot sekaisin. Vedä ne haluamaasi järjestykseen: kunkin lajin ylin toimii oletuksena.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-tallennus: kun yhdistät ämpäriin, päätepiste, ämpärin nimi ja käyttöavaimesi tallennetaan (salainen avain turvallisesti järjestelmäsi avainnippuun), ja esitykset, jotka avaat tai tallennat, lähetetään siihen tallennuspalveluun.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-tallennus: kun yhdistät arkistoon, käyttöpoletti tallennetaan (turvallisesti järjestelmäsi avainnippuun), ja esitykset, jotka tallennat, lähetetään sille palvelimelle committeina. Arkiston työkopio jää salaamattomana tälle laitteelle.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Tämän esityksen kielelle puuttuvat sairauksien nimet. Uskonto, poliittinen mielipide ja ammattiyhdistystermit tunnistetaan, ja tarkistusnumerolliset kuviot (hetu, IBAN, passi) toimivat aina — mutta älä luota siihen, että diagnoosi löytyy.',
  'niet getest': 'ei testattu',
  'Werkte op': 'Toimi',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Olet kirjautunut sisään, mutta sinulla ei ole tänne pääsyä. Salasana ei ole ongelma — pyydä ylläpitäjältä oikeuksia tähän kansioon.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Tunnuksesi on kelvollinen, mutta sillä ei ole tähän lupaa. Anna sille lisää oikeuksia tai odota, jos forge rajoittaa.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Tunnus on kelvollinen, mutta sillä ei ole tähän lupaa — anna sille lisää oikeuksia repositorioon.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Kirjautunut, mutta ei pääsyä — salasana ei ole ongelma. Pyydä oikeuksia tähän kansioon.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Tämä näyttää täydeltä DAV-osoitteelta. Nextcloudissa OciDeck päättelee polun itse — tähän kuuluu vain palvelin.',
  'Overnemen': 'Käytä',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV ei ole (oikein) määritetty — tarkista palvelintiedot kohdassa Asetukset → Tallennus.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git-repositoriota ei ole (oikein) määritetty — tarkista palvelin, omistaja ja repositorio kohdassa Asetukset → Tallennus.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Forgen palvelimen nimeä ei ole olemassa tai sitä ei voi hakea. Tarkista palvelimen URL-osoitteen kirjoitusasu.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Tällä forgella on yksityinen tai LAN-osoite. Merkitse se luotetuksi sisäiseksi kohdassa Asetukset → Tallennus.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge ei ole tavoitettavissa — tarkista yhteytesi ja palvelimen URL-osoite.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Kirjautuminen forgeen epäonnistui. Tarkista tunnus: se tarvitsee lukuoikeuden repositorioon ja kirjoitusoikeuden tallentamiseen.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Ei löytynyt repositoriosta — tai tunnuksesi ei saa nähdä sitä.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge palautti virheen. Yritä myöhemmin uudelleen.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Tämä osoite ei vastaa forgen tavoin. Onko forge-tyyppi kohdassa Asetukset → Tallennus oikea?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Määritä ensin WebDAV-palvelin kohdassa Asetukset → Tallennus.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Tarvitaan, kun forge on yksityisessä tai kotiverkossa. Ilman tätä merkintää turvatarkistus hylkää yksityisen osoitteen.',
  'Vul server-URL, eigenaar en repository in':
      'Täytä palvelimen URL, omistaja ja repositorio',
  'de standaardbranch heet': 'oletushaaran nimi on',
  'die wordt voortaan gebruikt': 'sitä käytetään tästä lähtien',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repositorio on vielä tyhjä; ensimmäinen tallennus täyttää sen',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'huomio: tämä tunnus saa vain lukea, joten tallennus epäonnistuu',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Kirjautuminen epäonnistui — tarkista tunnus. Se tarvitsee lukuoikeuden repositorioon ja kirjoitusoikeuden tallentaakseen.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repositoriota ei löytynyt — tai tunnuksesi ei saa nähdä sitä. Tarkista omistaja ja repositorion nimi.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Tämä osoite ei vastaa forgen tavoin. Onko valitsemasi forge-tyyppi oikea?',
  'kenteken': 'rekisterinumero',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Tämän esityksen kielelle ei ole avainsanaluetteloa erityisiin henkilötietoryhmiin. Tarkistusnumerolliset kuviot (hetu, IBAN, passi) toimivat; sanoja kuten "diagnoosi" tai "epäilty" ei tunnisteta.',
  'Landpakketten voor identificatienummers': 'Maapaketit tunnistenumeroille',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Numerot kuten alankomaalainen BSN tai puolalainen PESEL ovat maakohtaisia. Koko Eurooppa on päällä, koska useimmissa näistä numeroista on tarkistusnumero: niiden käyttöönotto ei juuri maksa vääriä hälytyksiä. IBAN, sähköposti, salaisuudet ja passirivit ovat tästä riippumattomia ja tarkistetaan aina.',
  'strafrechtelijk gegeven (verdachte)': 'rikosoikeudellinen tieto (epäilty)',
  'strafrechtelijk gegeven (aangever of slachtoffer)':
      'rikosoikeudellinen tieto (ilmoittaja tai uhri)',
  'strafrechtelijk gegeven (getuige)': 'rikosoikeudellinen tieto (todistaja)',
  'diagnosecode (ICD-10)': 'diagnoosikoodi (ICD-10)',
  'geneesmiddelcode (ATC)': 'lääkekoodi (ATC)',
  'geboortedatum': 'syntymäaika',
  'locatiecoördinaten': 'sijaintikoordinaatit',
  'MAC-adres van een apparaat': 'laitteen MAC-osoite',
  'IMEI van een toestel': 'puhelimen IMEI',
  'ICCID van een simkaart': 'SIM-kortin ICCID',
  'IMSI van een abonnee': 'tilaajan IMSI',
  'sociale-mediaprofiel': 'sosiaalisen median profiili',
  'advertentie- of apparaat-ID': 'mainos- tai laitetunnus',
  'IP-adres': 'IP-osoite',
  'machineleesbare zone van een paspoort of ID':
      'passin tai henkilökortin koneluettava alue',
  'De endpoint-naam bestaat niet, of is niet op te zoeken. Controleer het endpoint op een typefout.':
      'Päätepisteen nimeä ei ole olemassa tai sitä ei voi hakea. Tarkista päätepisteen kirjoitusasu.',
  'De endpoint-naam bestaat niet. Controleer het endpoint op een typefout.':
      'Päätepisteen nimeä ei ole olemassa. Tarkista päätepisteen kirjoitusasu.',
  'De servernaam bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Palvelimen nimeä ei ole olemassa tai sitä ei voi hakea. Tarkista palvelimen URL-osoitteen kirjoitusasu.',
  'Deze server heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Tällä palvelimella on yksityinen tai LAN-osoite. Merkitse se luotetuksi sisäiseksi kohdassa Asetukset → Tallennus.',
  'De server stuurt door naar een ander adres. Vul dat adres rechtstreeks in — een omleiding volgen we niet, want die kan de veiligheidscontrole omzeilen.':
      'Palvelin ohjaa toiseen osoitteeseen. Syötä se osoite suoraan — emme seuraa uudelleenohjauksia, koska ne voivat ohittaa turvatarkistuksen.',
  'De servernaam bestaat niet. Controleer de server-URL op een typefout.':
